n = int(input())
a = list(map(int, input().split()))
even2odd = []
cnt = [0, 0]

for i in range(n):
    v = a[i]
    cnt[v & 1] += 1
    c = 0
    while v % 2 == 0:
        c += 1
        v //= 2

    if c > 0:
        even2odd.append(c)

m = n // 2

if cnt[0] == cnt[1]:
    print(0)
elif cnt[0] > cnt[1]:
    even2odd.sort()
    need = cnt[0] - m
    ans = sum(even2odd[:need])
    print(ans)
else:
    print(m - cnt[0])

```
