        print(ans)
    else:
        # 偶数多，需要把一些偶数变成奇数，贪心选择操作次数最小的
        even_to_odd_cost.sort()
        need = cnt_even - m
        ans = sum(even_to_odd_cost[:need])
        print(ans)

if __name__ == "__main__":
    main()
```
但是需要注意，cnt_odd > cnt_even时，ans = cnt_odd - m，正确。如果cnt_odd > cnt_even，则cnt_odd > m，cnt_odd - m = (cnt_odd - cnt_even)/2。这也就是奇数个数超出半数部分。

